 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # The most common color is the field; the other marker color(s) are points.
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] != background and grid[r][c] != 3]
    for i, (r1, c1) in enumerate(points):
        for r2, c2 in points[i + 1:]:
            if r1 == r2:
                for c in range(min(c1, c2) + 1, max(c1, c2)):
                    if out[r1][c] == background:
                        out[r1][c] = 3
            elif c1 == c2:
                for r in range(min(r1, r2) + 1, max(r1, r2)):
                    if out[r][c1] == background:
                        out[r][c1] = 3
    return out
